1	-- =============================================================================
2	-- EXPOSITORA (Pronta Entrega v2) — controle do estoque exposto no salão
3	--
4	-- Modelo: estoque (câmara fria/congelado) → EXPOSITORA (vitrines/balcão) → venda.
5	-- Total em loja = estoque.quantidade_atual + expositora_estoque.quantidade.
6	--
7	-- Ponto único de integração: trigger em movimentacoes. Toda saída de estoque
8	-- com motivo da família "exposição" credita a expositora NA MESMA TRANSAÇÃO:
9	--   · 'exposicao'                 → movimentação manual (página Pronta Entrega)
10	--   · 'saida_inteira_exposicao'   → bip de container inteiro (bipar_etiqueta etapa 'exposicao')
11	--   · 'retirada_avulsa_exposicao' → retirada parcial com destino expositora
12	--
13	-- Saldo da expositora PODE ficar negativo por design — mostra o furo de
14	-- processo (venda/perda sem registro de subida pra vitrine). Fase 2 (Degust)
15	-- vai lançar tipo='venda' no ledger.
16	--
17	-- Nada destrutivo: pronta_entrega_stock/logs permanecem como histórico.
18	-- =============================================================================
19	
20	-- ─────────────────────────────────────────────────────────────────────────────
21	-- 1) Tabelas: saldo + ledger append-only
22	-- ─────────────────────────────────────────────────────────────────────────────
23	
24	CREATE TABLE IF NOT EXISTS public.expositora_estoque (
25	  id                bigserial PRIMARY KEY,
26	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
27	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
28	  quantidade        numeric NOT NULL DEFAULT 0,  -- pode ser negativa (furo de processo visível)
29	  updated_at        timestamptz NOT NULL DEFAULT now(),
30	  UNIQUE (produto_master_id, loja_id)
31	);
32	
33	CREATE INDEX IF NOT EXISTS idx_expositora_estoque_loja
34	  ON public.expositora_estoque (loja_id);
35	
36	CREATE TABLE IF NOT EXISTS public.expositora_movimentacoes (
37	  id                bigserial PRIMARY KEY,
38	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
39	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
40	  tipo              text    NOT NULL CHECK (tipo IN ('entrada','saida','ajuste','venda')),
41	  quantidade        numeric NOT NULL,            -- magnitude do movimento (sempre > 0)
42	  saldo_anterior    numeric NOT NULL,
43	  saldo_novo        numeric NOT NULL,
44	  motivo            text    NOT NULL,
45	  movimentacao_id   integer REFERENCES public.movimentacoes(id) ON DELETE SET NULL,
46	  etiqueta_qr_uid   text,                        -- trace; sem FK de propósito (etiquetas podem ser limpas)
47	  usuario_id        uuid,
48	  usuario_nome      text,
49	  observacoes       text,
50	  created_at        timestamptz NOT NULL DEFAULT now()
51	);
52	
53	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_produto_data
54	  ON public.expositora_movimentacoes (loja_id, produto_master_id, created_at DESC);
55	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_data
56	  ON public.expositora_movimentacoes (loja_id, created_at DESC);
57	
58	-- RLS: leitura pra authenticated; escrita SÓ via funções SECURITY DEFINER
59	ALTER TABLE public.expositora_estoque        ENABLE ROW LEVEL SECURITY;
60	ALTER TABLE public.expositora_movimentacoes  ENABLE ROW LEVEL SECURITY;
61	
62	DROP POLICY IF EXISTS expositora_estoque_select ON public.expositora_estoque;
63	CREATE POLICY expositora_estoque_select
64	  ON public.expositora_estoque FOR SELECT TO authenticated USING (true);
65	
66	DROP POLICY IF EXISTS expositora_movimentacoes_select ON public.expositora_movimentacoes;
67	CREATE POLICY expositora_movimentacoes_select
68	  ON public.expositora_movimentacoes FOR SELECT TO authenticated USING (true);
69	
70	-- ─────────────────────────────────────────────────────────────────────────────
71	-- 2) Nova etapa 'exposicao' no CHECK de etiquetas_qr_eventos
72	-- ─────────────────────────────────────────────────────────────────────────────
73	
74	ALTER TABLE public.etiquetas_qr_eventos
75	  DROP CONSTRAINT IF EXISTS etiquetas_qr_eventos_etapa_check;
76	ALTER TABLE public.etiquetas_qr_eventos
77	  ADD CONSTRAINT etiquetas_qr_eventos_etapa_check CHECK (etapa = ANY (ARRAY[
78	    'geracao'::text, 'separacao'::text, 'conferencia'::text, 'entrada'::text,
79	    'saida'::text, 'consumo'::text, 'descarte'::text, 'reposicao'::text,
80	    'backfill'::text, 'exposicao'::text
81	  ]));
82	
83	-- ─────────────────────────────────────────────────────────────────────────────
84	-- 3) Helper interno: aplica delta no saldo da expositora + grava ledger
85	--    (lock por linha; cria a linha zerada se não existir)
86	-- ─────────────────────────────────────────────────────────────────────────────
87	
88	CREATE OR REPLACE FUNCTION public.fn_expositora_aplicar(
89	  p_produto_master_id integer,
90	  p_loja_id           integer,
91	  p_delta             numeric,   -- positivo soma, negativo subtrai
92	  p_tipo              text,      -- 'entrada' | 'saida' | 'ajuste' | 'venda'
93	  p_motivo            text,
94	  p_movimentacao_id   integer DEFAULT NULL,
95	  p_etiqueta_qr_uid   text    DEFAULT NULL,
96	  p_usuario_id        uuid    DEFAULT NULL,
97	  p_usuario_nome      text    DEFAULT NULL,
98	  p_observacoes       text    DEFAULT NULL
99	) RETURNS numeric
100	LANGUAGE plpgsql
101	SECURITY DEFINER
102	SET search_path TO 'public'
103	AS $$
104	DECLARE
105	  v_saldo_anterior numeric;
106	  v_saldo_novo     numeric;
107	BEGIN
108	  IF p_delta IS NULL OR p_delta = 0 THEN
109	    SELECT quantidade INTO v_saldo_anterior
110	      FROM public.expositora_estoque
111	     WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
112	    RETURN COALESCE(v_saldo_anterior, 0);
113	  END IF;
114	
115	  -- garante a linha e trava pra leitura consistente do saldo
116	  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
117	  VALUES (p_produto_master_id, p_loja_id, 0)
118	  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;
119	
120	  SELECT quantidade INTO v_saldo_anterior
121	    FROM public.expositora_estoque
122	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
123	   FOR UPDATE;
124	
125	  v_saldo_novo := v_saldo_anterior + p_delta;
126	
127	  UPDATE public.expositora_estoque
128	     SET quantidade = v_saldo_novo, updated_at = now()
129	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
130	
131	  INSERT INTO public.expositora_movimentacoes (
132	    produto_master_id, loja_id, tipo, quantidade, saldo_anterior, saldo_novo,
133	    motivo, movimentacao_id, etiqueta_qr_uid, usuario_id, usuario_nome, observacoes
134	  ) VALUES (
135	    p_produto_master_id, p_loja_id, p_tipo, ABS(p_delta), v_saldo_anterior, v_saldo_novo,
136	    p_motivo, p_movimentacao_id, p_etiqueta_qr_uid, p_usuario_id, p_usuario_nome, p_observacoes
137	  );
138	
139	  RETURN v_saldo_novo;
140	END;
141	$$;
142	
143	REVOKE EXECUTE ON FUNCTION public.fn_expositora_aplicar(integer,integer,numeric,text,text,integer,text,uuid,text,text) FROM PUBLIC, anon;
144	
145	-- ─────────────────────────────────────────────────────────────────────────────
146	-- 4) Trigger em movimentacoes: saída com motivo de exposição → credita expositora
147	--    (mesma transação que o débito de estoque feito por atualizar_estoque_e_alertas)
148	-- ─────────────────────────────────────────────────────────────────────────────
149	
150	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_expositora()
151	RETURNS trigger
152	LANGUAGE plpgsql
153	SECURITY DEFINER
154	SET search_path TO 'public'
155	AS $$
156	DECLARE
157	  v_user_id   uuid := auth.uid();
158	  v_user_nome text;
159	BEGIN
160	  IF NEW.tipo_movimentacao <> 'saida'
161	     OR COALESCE(NEW.motivo,'') NOT IN ('exposicao','saida_inteira_exposicao','retirada_avulsa_exposicao') THEN
162	    RETURN NEW;
163	  END IF;
164	  IF NEW.produto_master_id IS NULL OR NEW.loja_id IS NULL THEN
165	    RETURN NEW;
166	  END IF;
167	
168	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
169	    FROM auth.users WHERE id = v_user_id;
170	
171	  PERFORM public.fn_expositora_aplicar(
172	    NEW.produto_master_id, NEW.loja_id, NEW.quantidade,
173	    'entrada', NEW.motivo, NEW.id, NEW.etiqueta_qr_uid,
174	    v_user_id, v_user_nome, NEW.observacoes
175	  );
176	
177	  RETURN NEW;
178	END;
179	$$;
180	
181	DROP TRIGGER IF EXISTS trg_movimentacoes_expositora ON public.movimentacoes;
182	CREATE TRIGGER trg_movimentacoes_expositora
183	AFTER INSERT ON public.movimentacoes
184	FOR EACH ROW EXECUTE FUNCTION public.tg_movimentacoes_expositora();
185	
186	-- ─────────────────────────────────────────────────────────────────────────────
187	-- 5) RPC: mover manualmente do estoque pra expositora (página Pronta Entrega)
188	-- ─────────────────────────────────────────────────────────────────────────────
189	
190	CREATE OR REPLACE FUNCTION public.mover_para_expositora(
191	  p_produto_master_id integer,
192	  p_loja_id           integer,
193	  p_quantidade        numeric,
194	  p_observacoes       text DEFAULT NULL
195	) RETURNS jsonb
196	LANGUAGE plpgsql
197	SECURITY DEFINER
198	SET search_path TO 'public'
199	AS $$
200	DECLARE
201	  v_estoque_anterior numeric;
202	  v_estoque_novo     numeric;
203	  v_expositora       numeric;
204	  v_alertas          jsonb := '[]'::jsonb;
205	BEGIN
206	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
207	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
208	  END IF;
209	  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
210	    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
211	  END IF;
212	  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id AND ativo = true) THEN
213	    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado ou inativo');
214	  END IF;
215	
216	  SELECT quantidade_atual INTO v_estoque_anterior
217	    FROM public.estoque
218	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
219	   FOR UPDATE;
220	
221	  v_estoque_anterior := COALESCE(v_estoque_anterior, 0);
222	  v_estoque_novo     := v_estoque_anterior - p_quantidade;
223	
224	  IF v_estoque_novo < 0 THEN
225	    v_alertas := v_alertas || jsonb_build_array(
226	      format('Estoque da câmara ficou negativo (%s) — confira a contagem', v_estoque_novo));
227	  END IF;
228	
229	  -- débito do estoque (trigger atualizar_estoque_e_alertas) +
230	  -- crédito da expositora (trigger tg_movimentacoes_expositora) — atômico
231	  INSERT INTO public.movimentacoes (
232	    produto_master_id, tipo_movimentacao, quantidade,
233	    quantidade_anterior, quantidade_nova, motivo, observacoes,
234	    data_movimentacao, loja_id
235	  ) VALUES (
236	    p_produto_master_id, 'saida', p_quantidade,
237	    v_estoque_anterior, v_estoque_novo, 'exposicao',
238	    COALESCE(p_observacoes, 'Movido para expositora'),
239	    now(), p_loja_id
240	  );
241	
242	  SELECT quantidade INTO v_expositora
243	    FROM public.expositora_estoque
244	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
245	
246	  RETURN jsonb_build_object(
247	    'ok', true,
248	    'estoque_anterior',  v_estoque_anterior,
249	    'estoque_novo',      v_estoque_novo,
250	    'expositora_saldo',  COALESCE(v_expositora, 0),
251	    'alertas',           v_alertas
252	  );
253	END;
254	$$;
255	
256	REVOKE EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) FROM PUBLIC, anon;
257	GRANT  EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) TO authenticated;
258	
259	-- ─────────────────────────────────────────────────────────────────────────────
260	-- 6) RPC: ajuste da expositora com motivo (perda, vencido, degustação,
261	--    consumo interno, recontagem/contagem inicial). NÃO mexe no estoque.
262	-- ─────────────────────────────────────────────────────────────────────────────
263	
264	CREATE OR REPLACE FUNCTION public.ajustar_expositora(
265	  p_produto_master_id integer,
266	  p_loja_id           integer,
267	  p_quantidade        numeric,            -- delta (modo 'delta') ou saldo alvo (modo 'absoluto')
268	  p_modo              text DEFAULT 'delta',
269	  p_motivo            text DEFAULT 'outro',
270	  p_observacoes       text DEFAULT NULL
271	) RETURNS jsonb
272	LANGUAGE plpgsql
273	SECURITY DEFINER
274	SET search_path TO 'public'
275	AS $$
276	DECLARE
277	  v_user_id      uuid := auth.uid();
278	  v_user_nome    text;
279	  v_saldo_atual  numeric;
280	  v_delta        numeric;
281	  v_saldo_novo   numeric;
282	BEGIN
283	  IF p_modo NOT IN ('delta','absoluto') THEN
284	    RETURN jsonb_build_object('ok', false, 'erro', 'Modo inválido: ' || COALESCE(p_modo,'<null>'));
285	  END IF;
286	  IF p_motivo NOT IN ('perda','vencido','degustacao','consumo_interno','recontagem','contagem_inicial','outro') THEN
287	    RETURN jsonb_build_object('ok', false, 'erro', 'Motivo inválido: ' || COALESCE(p_motivo,'<null>'));
288	  END IF;
289	  IF p_quantidade IS NULL THEN
290	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade obrigatória');
291	  END IF;
292	  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
293	    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
294	  END IF;
295	  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id) THEN
296	    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado');
297	  END IF;
298	
299	  -- garante linha + trava antes de calcular delta (modo absoluto depende do saldo atual)
300	  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
301	  VALUES (p_produto_master_id, p_loja_id, 0)
302	  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;
303	
304	  SELECT quantidade INTO v_saldo_atual
305	    FROM public.expositora_estoque
306	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
307	   FOR UPDATE;
308	
309	  v_delta := CASE WHEN p_modo = 'absoluto' THEN p_quantidade - v_saldo_atual ELSE p_quantidade END;
310	
311	  IF v_delta = 0 THEN
312	    RETURN jsonb_build_object('ok', true, 'saldo', v_saldo_atual, 'delta', 0,
313	                              'mensagem', 'Saldo já estava no valor informado');
314	  END IF;
315	
316	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
317	    FROM auth.users WHERE id = v_user_id;
318	
319	  v_saldo_novo := public.fn_expositora_aplicar(
320	    p_produto_master_id, p_loja_id, v_delta,
321	    'ajuste', p_motivo, NULL, NULL,
322	    v_user_id, v_user_nome, p_observacoes
323	  );
324	
325	  RETURN jsonb_build_object('ok', true, 'saldo_anterior', v_saldo_atual,
326	                            'saldo', v_saldo_novo, 'delta', v_delta);
327	END;
328	$$;
329	
330	REVOKE EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) FROM PUBLIC, anon;
331	GRANT  EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) TO authenticated;
332	
333	-- ─────────────────────────────────────────────────────────────────────────────
334	-- 7) bipar_etiqueta: nova etapa 'exposicao' — container inteiro vai pra vitrine.
335	--    Etiqueta → 'consumida' (desembalada no salão); movimentação de saída do
336	--    estoque criada AQUI DENTRO (motivo 'saida_inteira_exposicao') pra garantir
337	--    atomicidade etiqueta + estoque + lotes + expositora.
338	--    Resto da função idêntico à versão em produção.
339	-- ─────────────────────────────────────────────────────────────────────────────
340	
341	CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
342	 RETURNS jsonb
343	 LANGUAGE plpgsql
344	 SECURITY DEFINER
345	 SET search_path TO 'public'
346	AS $function$
347	DECLARE
348	  v_etiqueta public.etiquetas_qr%ROWTYPE;
349	  v_user_id uuid := auth.uid();
350	  v_user_nome text;
351	  v_status_anterior text;
352	  v_status_novo text;
353	  v_loja_id integer;
354	  v_alertas jsonb := '[]'::jsonb;
355	  v_referencia_tipo text;
356	  v_referencia_id text;
357	  v_payload jsonb;
358	  v_pid_text text;
359	  v_pid_int integer;
360	  v_lote_uuid uuid;
361	  v_produto_nome text;
362	  v_lote_codigo text;
363	  v_lote_validade date;
364	  v_qty_interna numeric;
365	  -- exposição
366	  v_loja_eff integer;
367	  v_qtd_expor numeric;
368	  v_est_ant numeric;
369	BEGIN
370	  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte','exposicao') THEN
371	    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa);
372	  END IF;
373	
374	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
375	    FROM auth.users WHERE id = v_user_id;
376	
377	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
378	  v_referencia_tipo := p_contexto->>'referencia_tipo';
379	  v_referencia_id   := p_contexto->>'referencia_id';
380	  v_payload         := p_contexto->'payload';
381	
382	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
383	
384	  -- ── BACKFILL: etiqueta nova (nunca registrada) ──────────────────────────────
385	  IF NOT FOUND THEN
386	    IF v_payload IS NULL THEN
387	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill');
388	    END IF;
389	
390	    -- exposição exige loja conhecida (não há etiqueta pra herdar loja_atual_id)
391	    IF p_etapa = 'exposicao' AND v_loja_id IS NULL THEN
392	      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja_id no contexto');
393	    END IF;
394	
395	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
396	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
397	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
398	    END IF;
399	    v_pid_int     := v_pid_text::integer;
400	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
401	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
402	
403	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
404	
405	    -- Resolve lote_id de forma segura: se UUID do payload nao existe, cria/encontra
406	    -- por codigo+validade ou usa NULL. Nunca insere UUID morto (causa FK error).
407	    IF v_lote_uuid IS NOT NULL THEN
408	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade
409	        FROM public.lotes WHERE id = v_lote_uuid;
410	      IF NOT FOUND THEN
411	        -- UUID morto: tenta resolver por snapshot no payload
412	        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
413	        v_lote_validade := NULLIF(COALESCE(v_payload->>'val',  v_payload->>'v'),  '')::date;
414	        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
415	          v_lote_uuid := public.find_or_create_lote(
416	            v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL
417	          );
418	        ELSE
419	          v_lote_uuid := NULL;  -- sem como resolver; grava sem lote (FK permite NULL)
420	        END IF;
421	      END IF;
422	    END IF;
423	
424	    INSERT INTO public.etiquetas_qr (
425	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
426	      quantidade_disponivel, consumida_inteira,
427	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
428	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
429	      foi_separada, separada_at, separada_por,
430	      foi_conferida, conferida_at, conferida_por,
431	      backfilled, qr_payload
432	    ) VALUES (
433	      p_uid, v_pid_int, v_lote_uuid,
434	      COALESCE(v_payload->>'emb', v_payload->>'n'),
435	      v_qty_interna,
436	      CASE WHEN p_etapa = 'exposicao' THEN 0 ELSE v_qty_interna END,
437	      (p_etapa = 'exposicao'),
438	      v_produto_nome, v_lote_codigo, v_lote_validade,
439	      NULL, v_loja_id,
440	      CASE p_etapa
441	        WHEN 'separacao'  THEN 'gerada'
442	        WHEN 'conferencia' THEN 'gerada'
443	        WHEN 'entrada'    THEN 'recebida'
444	        WHEN 'saida'      THEN 'em_transito'
445	        WHEN 'consumo'    THEN 'consumida'
446	        WHEN 'descarte'   THEN 'descartada'
447	        WHEN 'exposicao'  THEN 'consumida'
448	      END,
449	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
450	      (p_etapa = 'separacao'),
451	      CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END,
452	      CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END,
453	      (p_etapa = 'conferencia'),
454	      CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END,
455	      CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END,
456	      true, v_payload
457	    ) RETURNING * INTO v_etiqueta;
458	
459	    -- exposição em backfill: registra a saída do estoque (crédito da expositora
460	    -- acontece via trigger tg_movimentacoes_expositora)
461	    IF p_etapa = 'exposicao' THEN
462	      SELECT quantidade_atual INTO v_est_ant
463	        FROM public.estoque
464	       WHERE produto_master_id = v_pid_int AND loja_id = v_loja_id
465	       FOR UPDATE;
466	      v_est_ant := COALESCE(v_est_ant, 0);
467	
468	      INSERT INTO public.movimentacoes (
469	        produto_master_id, tipo_movimentacao, quantidade,
470	        quantidade_anterior, quantidade_nova, motivo, observacoes,
471	        data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
472	      ) VALUES (
473	        v_pid_int, 'saida', v_qty_interna,
474	        v_est_ant, v_est_ant - v_qty_interna,
475	        'saida_inteira_exposicao',
476	        format('Exposicao na vitrine (backfill) — UID %s', p_uid),
477	        NOW(), v_loja_id, v_lote_uuid, p_uid
478	      );
479	    END IF;
480	
481	    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
482	    INSERT INTO public.etiquetas_qr_eventos (
483	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
484	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
485	    ) VALUES (
486	      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
487	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
488	      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
489	    );
490	
491	    RETURN jsonb_build_object(
492	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
493	      'status_anterior', NULL, 'status_novo', v_etiqueta.status,
494	      'alertas', v_alertas, 'backfilled', true,
495	      'quantidade_exposta', CASE WHEN p_etapa = 'exposicao' THEN v_qty_interna ELSE NULL END
496	    );
497	  END IF;
498	  -- ── FIM BACKFILL ─────────────────────────────────────────────────────────────
499	
500	  v_status_anterior := v_etiqueta.status;
501	
502	  IF v_etiqueta.status = 'descartada' THEN
503	    RETURN jsonb_build_object(
504	      'ok', false, 'erro', 'Etiqueta descartada'
505	        || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
506	                THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')'
507	                ELSE '' END,
508	      'etiqueta', to_jsonb(v_etiqueta)
509	    );
510	  END IF;
511	
512	  IF v_etiqueta.lote_validade_snapshot IS NOT NULL
513	     AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
514	    v_alertas := v_alertas || jsonb_build_array(
515	      format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))
516	    );
517	  END IF;
518	
519	  -- ── SEPARAÇÃO ────────────────────────────────────────────────────────────────
520	  IF p_etapa = 'separacao' THEN
521	    IF v_etiqueta.foi_separada THEN
522	      RETURN jsonb_build_object(
523	        'ok', false,
524	        'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid),
525	        'etiqueta', to_jsonb(v_etiqueta),
526	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
527	      );
528	    END IF;
529	    UPDATE public.etiquetas_qr
530	       SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id,
531	           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
532	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
533	    INSERT INTO public.etiquetas_qr_eventos (
534	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
535	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
536	    ) VALUES (
537	      p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior,
538	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
539	      p_contexto - 'payload'
540	    );
541	    RETURN jsonb_build_object(
542	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
543	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
544	      'alertas', v_alertas, 'backfilled', false
545	    );
546	  END IF;
547	
548	  -- ── CONFERÊNCIA ──────────────────────────────────────────────────────────────
549	  IF p_etapa = 'conferencia' THEN
550	    IF v_etiqueta.foi_conferida THEN
551	      RETURN jsonb_build_object(
552	        'ok', false,
553	        'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid),
554	        'etiqueta', to_jsonb(v_etiqueta),
555	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
556	      );
557	    END IF;
558	    UPDATE public.etiquetas_qr
559	       SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id,
560	           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
561	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
562	    INSERT INTO public.etiquetas_qr_eventos (
563	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
564	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
565	    ) VALUES (
566	      p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior,
567	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
568	      p_contexto - 'payload'
569	    );
570	    RETURN jsonb_build_object(
571	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
572	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
573	      'alertas', v_alertas, 'backfilled', false
574	    );
575	  END IF;
576	
577	  -- ── EXPOSIÇÃO (container inteiro → vitrine) ──────────────────────────────────
578	  IF p_etapa = 'exposicao' THEN
579	    IF v_etiqueta.status NOT IN ('gerada','recebida','aberta') THEN
580	      RETURN jsonb_build_object(
581	        'ok', false,
582	        'erro', format('Etiqueta %s esta com status "%s" — nao pode ir pra expositora', p_uid, v_status_anterior),
583	        'etiqueta', to_jsonb(v_etiqueta),
584	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
585	      );
586	    END IF;
587	
588	    v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
589	    IF v_loja_eff IS NULL THEN
590	      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja conhecida (contexto ou etiqueta)');
591	    END IF;
592	
593	    v_qtd_expor := COALESCE(v_etiqueta.quantidade_disponivel, v_etiqueta.quantidade_interna, 1);
594	    IF v_qtd_expor <= 0 THEN
595	      RETURN jsonb_build_object('ok', false, 'erro', 'Container vazio — nada a expor',
596	                                'etiqueta', to_jsonb(v_etiqueta));
597	    END IF;
598	
599	    SELECT quantidade_atual INTO v_est_ant
600	      FROM public.estoque
601	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
602	     FOR UPDATE;
603	    v_est_ant := COALESCE(v_est_ant, 0);
604	
605	    -- saída do estoque; trigger credita expositora na mesma transação
606	    INSERT INTO public.movimentacoes (
607	      produto_master_id, tipo_movimentacao, quantidade,
608	      quantidade_anterior, quantidade_nova, motivo, observacoes,
609	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
610	    ) VALUES (
611	      v_etiqueta.produto_master_id, 'saida', v_qtd_expor,
612	      v_est_ant, v_est_ant - v_qtd_expor,
613	      'saida_inteira_exposicao',
614	      format('Exposicao na vitrine — UID %s', p_uid),
615	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
616	    );
617	
618	    UPDATE public.etiquetas_qr
619	       SET status = 'consumida', consumida_inteira = TRUE, quantidade_disponivel = 0,
620	           loja_atual_id = v_loja_eff
621	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
622	
623	    INSERT INTO public.etiquetas_qr_eventos (
624	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
625	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
626	    ) VALUES (
627	      p_uid, 'bipada_exposicao', 'exposicao', v_status_anterior, 'consumida',
628	      v_loja_eff, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
629	      (p_contexto - 'payload') || jsonb_build_object('quantidade_exposta', v_qtd_expor)
630	    );
631	
632	    RETURN jsonb_build_object(
633	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
634	      'status_anterior', v_status_anterior, 'status_novo', 'consumida',
635	      'quantidade_exposta', v_qtd_expor,
636	      'alertas', v_alertas, 'backfilled', false
637	    );
638	  END IF;
639	
640	  -- ── TRANSIÇÕES DE STATUS (entrada/saida/consumo/descarte) ───────────────────
641	  v_status_novo := CASE p_etapa
642	    WHEN 'saida' THEN
643	      CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito'
644	           ELSE NULL END
645	    WHEN 'entrada' THEN
646	      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida'
647	           WHEN v_etiqueta.status = 'recebida'
648	                AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
649	           ELSE NULL END
650	    WHEN 'consumo'  THEN 'consumida'
651	    WHEN 'descarte' THEN 'descartada'
652	  END;
653	
654	  IF v_status_novo IS NULL THEN
655	    RETURN jsonb_build_object(
656	      'ok', false,
657	      'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior),
658	      'etiqueta', to_jsonb(v_etiqueta)
659	    );
660	  END IF;
661	
662	  UPDATE public.etiquetas_qr
663	     SET status = v_status_novo,
664	         loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
665	   WHERE uid = p_uid RETURNING * INTO v_etiqueta;
666	
667	  INSERT INTO public.etiquetas_qr_eventos (
668	    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
669	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
670	  ) VALUES (
671	    p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
672	    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
673	    p_contexto - 'payload'
674	  );
675	
676	  RETURN jsonb_build_object(
677	    'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
678	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
679	    'alertas', v_alertas, 'backfilled', false
680	  );
681	END;
682	$function$;
683	
684	-- ─────────────────────────────────────────────────────────────────────────────
685	-- 8) bipar_retirada_avulsa: contexto.destino = 'expositora' → a própria RPC
686	--    registra a movimentação de saída (motivo 'retirada_avulsa_exposicao');
687	--    o trigger credita a expositora. Frontend NÃO insere movimentação nesse caso
688	--    (resposta traz movimentacao_registrada = true).
689	--    Sem destino (default 'saida'): comportamento idêntico ao atual.
690	-- ─────────────────────────────────────────────────────────────────────────────
691	
692	CREATE OR REPLACE FUNCTION public.bipar_retirada_avulsa(p_uid text, p_quantidade numeric, p_contexto jsonb DEFAULT '{}'::jsonb)
693	 RETURNS jsonb
694	 LANGUAGE plpgsql
695	 SECURITY DEFINER
696	 SET search_path TO 'public'
697	AS $function$
698	DECLARE
699	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
700	  v_user_id             uuid := auth.uid();
701	  v_user_nome           text;
702	  v_loja_id             integer;
703	  v_referencia_tipo     text;
704	  v_referencia_id       text;
705	  v_payload             jsonb;
706	  v_disponivel_apos     numeric;
707	  v_status_anterior     text;
708	  v_status_novo         text;
709	  v_pid_text            text;
710	  v_pid_int             integer;
711	  v_lote_uuid           uuid;
712	  v_produto_nome        text;
713	  v_lote_codigo         text;
714	  v_lote_validade       date;
715	  v_qty_interna         numeric;
716	  -- destino expositora
717	  v_destino             text;
718	  v_loja_eff            integer;
719	  v_est_ant             numeric;
720	  v_mov_registrada      boolean := false;
721	BEGIN
722	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
723	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
724	  END IF;
725	
726	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
727	  v_referencia_tipo := p_contexto->>'referencia_tipo';
728	  v_referencia_id   := p_contexto->>'referencia_id';
729	  v_payload         := p_contexto->'payload';
730	  v_destino         := COALESCE(NULLIF(p_contexto->>'destino',''), 'saida');
731	
732	  IF v_destino NOT IN ('saida','expositora') THEN
733	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino invalido: ' || v_destino);
734	  END IF;
735	
736	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
737	
738	  -- ===== BACKFILL legacy: etiqueta sem row mas com payload no QR =====
739	  IF NOT FOUND THEN
740	    IF v_payload IS NULL THEN
741	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada (sem payload para backfill)');
742	    END IF;
743	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
744	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
745	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
746	    END IF;
747	    v_pid_int     := v_pid_text::integer;
748	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
749	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
750	
751	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
752	    IF v_lote_uuid IS NOT NULL THEN
753	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
754	    END IF;
755	
756	    INSERT INTO public.etiquetas_qr (
757	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
758	      quantidade_disponivel, consumida_inteira,
759	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
760	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
761	      backfilled, qr_payload
762	    ) VALUES (
763	      p_uid, v_pid_int, v_lote_uuid,
764	      COALESCE(v_payload->>'emb', v_payload->>'n'),
765	      v_qty_interna, v_qty_interna, false,
766	      v_produto_nome, v_lote_codigo, v_lote_validade,
767	      NULL, v_loja_id, 'gerada',
768	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
769	      true, v_payload
770	    )
771	    RETURNING * INTO v_etiqueta;
772	
773	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
774	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
775	      VALUES (p_uid, 'backfilled', 'backfill', NULL, 'gerada',
776	      v_loja_id, v_user_id, COALESCE((SELECT raw_user_meta_data->>'nome' FROM auth.users WHERE id = v_user_id), NULL),
777	      v_referencia_tipo, v_referencia_id,
778	      jsonb_build_object('etapa_origem', 'retirada_avulsa', 'payload', v_payload));
779	  END IF;
780	
781	  IF v_etiqueta.consumida_inteira OR v_etiqueta.status = 'consumida' THEN
782	    RETURN jsonb_build_object('ok', false,
783	      'erro', format('Etiqueta %s ja foi consumida totalmente', p_uid),
784	      'etiqueta', to_jsonb(v_etiqueta));
785	  END IF;
786	  IF v_etiqueta.status = 'descartada' THEN
787	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
788	  END IF;
789	
790	  IF p_quantidade > v_etiqueta.quantidade_disponivel THEN
791	    RETURN jsonb_build_object('ok', false,
792	      'erro', format('Container so tem %s disponivel (pediu %s)', v_etiqueta.quantidade_disponivel, p_quantidade),
793	      'etiqueta', to_jsonb(v_etiqueta));
794	  END IF;
795	
796	  -- destino expositora exige loja conhecida — validar ANTES de qualquer escrita
797	  v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
798	  IF v_destino = 'expositora' AND v_loja_eff IS NULL THEN
799	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino expositora exige loja conhecida (contexto ou etiqueta)');
800	  END IF;
801	
802	  v_disponivel_apos := v_etiqueta.quantidade_disponivel - p_quantidade;
803	  v_status_anterior := v_etiqueta.status;
804	  v_status_novo := CASE
805	    WHEN v_disponivel_apos = 0 THEN 'consumida'
806	    WHEN v_disponivel_apos < v_etiqueta.quantidade_interna THEN 'aberta'
807	    ELSE v_status_anterior
808	  END;
809	
810	  UPDATE public.etiquetas_qr SET
811	    quantidade_disponivel = v_disponivel_apos,
812	    consumida_inteira     = (v_disponivel_apos = 0),
813	    status                = v_status_novo,
814	    loja_atual_id         = COALESCE(v_loja_id, loja_atual_id)
815	  WHERE uid = p_uid RETURNING * INTO v_etiqueta;
816	
817	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
818	
819	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
820	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
821	    VALUES (p_uid,
822	      CASE WHEN v_disponivel_apos = 0 THEN 'consumida_total' ELSE 'retirada_avulsa' END,
823	      'consumo', v_status_anterior, v_status_novo,
824	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
825	      jsonb_build_object(
826	        'quantidade_retirada', p_quantidade,
827	        'quantidade_disponivel_antes', v_etiqueta.quantidade_interna - v_disponivel_apos + p_quantidade,
828	        'quantidade_disponivel_apos', v_disponivel_apos,
829	        'consumida_inteira', v_etiqueta.consumida_inteira,
830	        'destino', v_destino));
831	
832	  -- destino expositora: movimentação de saída do estoque registrada AQUI
833	  -- (trigger credita a expositora na mesma transação)
834	  IF v_destino = 'expositora' THEN
835	    SELECT quantidade_atual INTO v_est_ant
836	      FROM public.estoque
837	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
838	     FOR UPDATE;
839	    v_est_ant := COALESCE(v_est_ant, 0);
840	
841	    INSERT INTO public.movimentacoes (
842	      produto_master_id, tipo_movimentacao, quantidade,
843	      quantidade_anterior, quantidade_nova, motivo, observacoes,
844	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
845	    ) VALUES (
846	      v_etiqueta.produto_master_id, 'saida', p_quantidade,
847	      v_est_ant, v_est_ant - p_quantidade,
848	      'retirada_avulsa_exposicao',
849	      format('Retirada avulsa pra vitrine — UID %s', p_uid),
850	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
851	    );
852	    v_mov_registrada := true;
853	  END IF;
854	
855	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
856	    'quantidade_retirada', p_quantidade, 'quantidade_disponivel', v_disponivel_apos,
857	    'consumida_inteira', v_etiqueta.consumida_inteira,
858	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
859	    'destino', v_destino, 'movimentacao_registrada', v_mov_registrada);
860	END;
861	$function$;
