869	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
870	 RETURNS trigger
871	 LANGUAGE plpgsql
872	 SECURITY DEFINER
873	 SET search_path TO 'public'
874	AS $function$
875	BEGIN
876	  IF COALESCE(NEW.motivo,'') NOT IN (
877	       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
878	       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa',
879	       'saida_inteira_exposicao', 'retirada_avulsa_exposicao'
880	     ) THEN
881	    RETURN NEW;
882	  END IF;
883	
884	  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
885	    RETURN NEW;
886	  END IF;
887	
888	  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
889	  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
890	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
891	
892	  IF NEW.tipo_movimentacao = 'entrada' THEN
893	    UPDATE public.estoque_lotes
894	       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
895	     WHERE lote_id = NEW.lote_id
896	       AND produto_id = NEW.produto_master_id
897	       AND loja_id = NEW.loja_id;
898	
899	  ELSIF NEW.tipo_movimentacao = 'saida' THEN
900	    UPDATE public.estoque_lotes
901	       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
902	     WHERE lote_id = NEW.lote_id
903	       AND produto_id = NEW.produto_master_id
904	       AND loja_id = NEW.loja_id;
905	  END IF;
906	
907	  -- Sem linha pra esse (lote, produto, loja) e e entrada -> cria com a loja correta.
908	  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
909	    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
910	    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
911	  END IF;
912	
913	  RETURN NEW;
914	END;
