1	/**
2	 * @module features/pronta-entrega/model/saldos
3	 *
4	 * Funções puras do domínio Pronta Entrega: merge dos saldos de câmara fria
5	 * (`estoque`) com os saldos de vitrine (`expositora_estoque`) e filtro de
6	 * busca por nome. Sem dependências de React/Supabase — testável isolado.
7	 */
8	
9	/** Fábrica (loja_id=1) não tem expositora — a página é exclusiva das lojas. */
10	export const FABRICA_LOJA_ID = 1;
11	
12	/** Linha crua de uma das fontes (estoque ou expositora) já com join de produto. */
13	export interface SaldoSourceRow {
14	  produtoId: number;
15	  nome: string;
16	  setor: string | null;
17	  quantidade: number;
18	}
19	
20	/** Saldo unificado de um produto na loja: câmara fria + expositora. */
21	export interface SaldoRow {
22	  produtoId: number;
23	  nome: string;
24	  setor: string | null;
25	  /** Quantidade na câmara fria/congelado (`estoque.quantidade_atual`). */
26	  estoque: number;
27	  /** Quantidade exposta no salão (`expositora_estoque.quantidade`). Pode ser negativa (furo de processo). */
28	  expositora: number;
29	  /** estoque + expositora. */
30	  total: number;
31	}
32	
33	/**
34	 * Faz o merge por `produtoId` das linhas de estoque (câmara) com as da
35	 * expositora. Mantém apenas produtos com estoque \> 0 OU expositora ≠ 0,
36	 * e ordena por nome (pt-BR).
37	 *
38	 * @param estoqueRows - Linhas da câmara fria (quantidade_atual).
39	 * @param expositoraRows - Linhas da expositora (quantidade; pode ser negativa).
40	 * @returns Saldos unificados, filtrados e ordenados por nome.
41	 */
42	export function mergeSaldos(
43	  estoqueRows: SaldoSourceRow[],
44	  expositoraRows: SaldoSourceRow[],
45	): SaldoRow[] {
46	  const byProduto = new Map<number, SaldoRow>();
47	
48	  for (const row of estoqueRows) {
49	    const existing = byProduto.get(row.produtoId);
50	    if (existing) {
51	      existing.estoque += row.quantidade;
52	    } else {
53	      byProduto.set(row.produtoId, {
54	        produtoId: row.produtoId,
55	        nome: row.nome,
56	        setor: row.setor,
57	        estoque: row.quantidade,
58	        expositora: 0,
59	        total: 0,
60	      });
61	    }
62	  }
63	
64	  for (const row of expositoraRows) {
65	    const existing = byProduto.get(row.produtoId);
66	    if (existing) {
67	      existing.expositora += row.quantidade;
68	      if (!existing.nome && row.nome) existing.nome = row.nome;
69	      if (existing.setor === null && row.setor !== null) existing.setor = row.setor;
70	    } else {
71	      byProduto.set(row.produtoId, {
72	        produtoId: row.produtoId,
73	        nome: row.nome,
74	        setor: row.setor,
75	        estoque: 0,
76	        expositora: row.quantidade,
77	        total: 0,
78	      });
79	    }
80	  }
81	
82	  return [...byProduto.values()]
83	    .filter((r) => r.estoque > 0 || r.expositora !== 0)
84	    .map((r) => ({ ...r, total: r.estoque + r.expositora }))
85	    .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
86	}
87	
88	/** Normaliza texto pra busca: minúsculas e sem acentos. */
89	export function normalizeSearchText(value: string): string {
90	  return value
91	    .toLowerCase()
92	    .normalize('NFD')
93	    .replace(/[\u0300-\u036f]/g, '');
94	}
95	
96	/**
97	 * Filtra os saldos pelo nome do produto (case/acento-insensível).
98	 *
99	 * @param rows - Saldos unificados.
100	 * @param search - Termo de busca digitado pelo usuário.
101	 * @returns Linhas cujo nome contém o termo; todas se o termo for vazio.
102	 */
103	export function filterSaldos(rows: SaldoRow[], search: string): SaldoRow[] {
104	  const term = normalizeSearchText(search.trim());
105	  if (!term) return rows;
106	  return rows.filter((r) => normalizeSearchText(r.nome).includes(term));
107	}
