1	/**
2	 * @module features/pronta-entrega/model/useProntaEntregaSaldos
3	 *
4	 * Query unificada dos saldos da loja: câmara fria (`estoque`) + vitrine
5	 * (`expositora_estoque`), com join em `produtos_master` (apenas ativos).
6	 * O merge por produto é feito pela função pura {@link mergeSaldos}.
7	 */
8	
9	import { useQuery } from '@tanstack/react-query';
10	import { supabase } from '@/integrations/supabase/client';
11	import {
12	  FABRICA_LOJA_ID,
13	  mergeSaldos,
14	  type SaldoRow,
15	  type SaldoSourceRow,
16	} from './saldos';
17	
18	export { mergeSaldos, filterSaldos, FABRICA_LOJA_ID } from './saldos';
19	export type { SaldoRow, SaldoSourceRow } from './saldos';
20	
21	export const prontaEntregaKeys = {
22	  saldos: (lojaId: number | null) => ['pronta-entrega', 'saldos', lojaId] as const,
23	  historico: (lojaId: number | null) => ['pronta-entrega', 'historico', lojaId] as const,
24	};
25	
26	interface ProdutoJoin {
27	  nome: string;
28	  setor: string | null;
29	}
30	
31	async function fetchSaldos(lojaId: number): Promise<SaldoRow[]> {
32	  const [estoqueRes, expositoraRes] = await Promise.all([
33	    supabase
34	      .from('estoque')
35	      .select('produto_master_id, quantidade_atual, produtos_master!inner(nome, setor, ativo)')
36	      .eq('loja_id', lojaId)
37	      .eq('produtos_master.ativo', true)
38	      .not('produto_master_id', 'is', null)
39	      .gt('quantidade_atual', 0),
40	    supabase
41	      .from('expositora_estoque')
42	      .select('produto_master_id, quantidade, produtos_master!inner(nome, setor, ativo)')
43	      .eq('loja_id', lojaId)
44	      .eq('produtos_master.ativo', true),
45	  ]);
46	
47	  if (estoqueRes.error) throw estoqueRes.error;
48	  if (expositoraRes.error) throw expositoraRes.error;
49	
50	  const estoqueRows: SaldoSourceRow[] = (estoqueRes.data ?? []).map((row) => {
51	    const produto = row.produtos_master as ProdutoJoin;
52	    return {
53	      produtoId: row.produto_master_id as number,
54	      nome: produto?.nome ?? `Produto #${row.produto_master_id}`,
55	      setor: produto?.setor ?? null,
56	      quantidade: row.quantidade_atual ?? 0,
57	    };
58	  });
59	
60	  const expositoraRows: SaldoSourceRow[] = (expositoraRes.data ?? []).map((row) => {
61	    const produto = row.produtos_master as ProdutoJoin;
62	    return {
63	      produtoId: row.produto_master_id,
64	      nome: produto?.nome ?? `Produto #${row.produto_master_id}`,
65	      setor: produto?.setor ?? null,
66	      quantidade: row.quantidade ?? 0,
67	    };
68	  });
69	
70	  return mergeSaldos(estoqueRows, expositoraRows);
71	}
72	
73	/**
74	 * Hook de saldos unificados da Pronta Entrega para uma loja.
75	 * Desabilitado quando não há loja selecionada ou quando a loja é a Fábrica
76	 * (que não tem expositora).
77	 *
78	 * @param lojaId - Loja selecionada (null enquanto o contexto carrega).
79	 */
80	export function useProntaEntregaSaldos(lojaId: number | null) {
81	  const enabled = lojaId !== null && lojaId !== FABRICA_LOJA_ID;
82	
83	  const query = useQuery({
84	    queryKey: prontaEntregaKeys.saldos(lojaId),
85	    queryFn: () => fetchSaldos(lojaId as number),
86	    enabled,
87	    staleTime: 30_000,
88	  });
89	
90	  return {
91	    rows: query.data ?? [],
92	    isLoading: enabled && query.isLoading,
93	    isError: query.isError,
94	    refetch: query.refetch,
95	  };
96	}
