1	/**
2	 * @module features/pronta-entrega/model/useExpositoraMutations
3	 *
4	 * Mutations da expositora via RPCs atômicos do banco:
5	 * - `mover_para_expositora` — dá baixa na câmara (estoque) e credita a vitrine;
6	 * - `ajustar_expositora` — ajusta só a vitrine (delta ou recontagem absoluta).
7	 *
8	 * Respostas `{ok:false, erro}` viram erro (toast destrutivo); `alertas[]` do
9	 * retorno são exibidos como toasts de aviso. Toasts de sucesso ficam a cargo
10	 * de quem chama (pra fluxos em lote não spammarem).
11	 */
12	
13	import { useMutation, useQueryClient } from '@tanstack/react-query';
14	import { toast } from 'sonner';
15	import { supabase } from '@/integrations/supabase/client';
16	import { prontaEntregaKeys } from './useProntaEntregaSaldos';
17	import type { AjusteMotivo } from './motivos';
18	
19	export interface MoverParaExpositoraInput {
20	  produtoId: number;
21	  quantidade: number;
22	  observacoes?: string;
23	}
24	
25	export interface MoverParaExpositoraResult {
26	  ok: boolean;
27	  erro?: string;
28	  estoque_anterior?: number;
29	  estoque_novo?: number;
30	  expositora_saldo?: number;
31	  alertas?: string[];
32	}
33	
34	export interface AjustarExpositoraInput {
35	  produtoId: number;
36	  quantidade: number;
37	  modo: 'delta' | 'absoluto';
38	  motivo: AjusteMotivo;
39	  observacoes?: string;
40	}
41	
42	export interface AjustarExpositoraResult {
43	  ok: boolean;
44	  erro?: string;
45	  saldo_anterior?: number;
46	  saldo?: number;
47	  delta?: number;
48	}
49	
50	/**
51	 * Mutations da expositora pra loja selecionada. Invalida saldos + histórico
52	 * em caso de sucesso.
53	 *
54	 * @param lojaId - Loja alvo das operações (null desabilita na prática:
55	 * mutations rejeitam com erro amigável).
56	 */
57	export function useExpositoraMutations(lojaId: number | null) {
58	  const queryClient = useQueryClient();
59	
60	  const invalidate = () => {
61	    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.saldos(lojaId) });
62	    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.historico(lojaId) });
63	  };
64	
65	  const mover = useMutation({
66	    mutationFn: async (input: MoverParaExpositoraInput): Promise<MoverParaExpositoraResult> => {
67	      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
68	      const { data, error } = await supabase.rpc('mover_para_expositora', {
69	        p_produto_master_id: input.produtoId,
70	        p_loja_id: lojaId,
71	        p_quantidade: input.quantidade,
72	        p_observacoes: input.observacoes,
73	      });
74	      if (error) throw new Error(error.message);
75	      const result = data as unknown as MoverParaExpositoraResult;
76	      if (!result?.ok) {
77	        throw new Error(result?.erro ?? 'Erro ao mover produto para a expositora.');
78	      }
79	      return result;
80	    },
81	    onSuccess: (result) => {
82	      invalidate();
83	      for (const alerta of result.alertas ?? []) {
84	        toast.warning(alerta);
85	      }
86	    },
87	    onError: (err: Error) => {
88	      toast.error(err.message);
89	    },
90	  });
91	
92	  const ajustar = useMutation({
93	    mutationFn: async (input: AjustarExpositoraInput): Promise<AjustarExpositoraResult> => {
94	      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
95	      const { data, error } = await supabase.rpc('ajustar_expositora', {
96	        p_produto_master_id: input.produtoId,
97	        p_loja_id: lojaId,
98	        p_quantidade: input.quantidade,
99	        p_modo: input.modo,
100	        p_motivo: input.motivo,
101	        p_observacoes: input.observacoes,
102	      });
103	      if (error) throw new Error(error.message);
104	      const result = data as unknown as AjustarExpositoraResult;
105	      if (!result?.ok) {
106	        throw new Error(result?.erro ?? 'Erro ao ajustar a expositora.');
107	      }
108	      return result;
109	    },
110	    onSuccess: () => {
111	      invalidate();
112	    },
113	    onError: (err: Error) => {
114	      toast.error(err.message);
115	    },
116	  });
117	
118	  return { mover, ajustar };
119	}
