1	/**
2	 * @module features/pronta-entrega/model/useExpositoraHistorico
3	 *
4	 * Query do ledger `expositora_movimentacoes` da loja (últimos 200, desc),
5	 * com nome do produto resolvido via join em `produtos_master`.
6	 */
7	
8	import { useQuery } from '@tanstack/react-query';
9	import { supabase } from '@/integrations/supabase/client';
10	import { FABRICA_LOJA_ID } from './saldos';
11	import { prontaEntregaKeys } from './useProntaEntregaSaldos';
12	
13	export interface ExpositoraLedgerRow {
14	  id: number;
15	  tipo: string;
16	  quantidade: number;
17	  saldoAnterior: number;
18	  saldoNovo: number;
19	  motivo: string;
20	  observacoes: string | null;
21	  usuarioNome: string | null;
22	  createdAt: string;
23	  produtoNome: string;
24	}
25	
26	async function fetchHistorico(lojaId: number): Promise<ExpositoraLedgerRow[]> {
27	  const { data, error } = await supabase
28	    .from('expositora_movimentacoes')
29	    .select(
30	      'id, tipo, quantidade, saldo_anterior, saldo_novo, motivo, observacoes, usuario_nome, created_at, produto_master_id, produtos_master(nome)',
31	    )
32	    .eq('loja_id', lojaId)
33	    .order('created_at', { ascending: false })
34	    .limit(200);
35	
36	  if (error) throw error;
37	
38	  return (data ?? []).map((row) => ({
39	    id: row.id,
40	    tipo: row.tipo,
41	    quantidade: row.quantidade,
42	    saldoAnterior: row.saldo_anterior,
43	    saldoNovo: row.saldo_novo,
44	    motivo: row.motivo,
45	    observacoes: row.observacoes,
46	    usuarioNome: row.usuario_nome,
47	    createdAt: row.created_at,
48	    produtoNome:
49	      (row.produtos_master as { nome: string } | null)?.nome ??
50	      `Produto #${row.produto_master_id}`,
51	  }));
52	}
53	
54	/**
55	 * Hook do histórico da expositora. Só busca quando `enabled` (ex.: sheet
56	 * aberto) e quando há loja válida (não-Fábrica).
57	 *
58	 * @param lojaId - Loja do ledger.
59	 * @param enabled - Liga/desliga a query (ex.: visibilidade do sheet).
60	 */
61	export function useExpositoraHistorico(lojaId: number | null, enabled: boolean) {
62	  const queryEnabled = enabled && lojaId !== null && lojaId !== FABRICA_LOJA_ID;
63	
64	  const query = useQuery({
65	    queryKey: prontaEntregaKeys.historico(lojaId),
66	    queryFn: () => fetchHistorico(lojaId as number),
67	    enabled: queryEnabled,
68	    staleTime: 15_000,
69	  });
70	
71	  return {
72	    entries: query.data ?? [],
73	    isLoading: queryEnabled && query.isLoading,
74	    isError: query.isError,
75	    refetch: query.refetch,
76	  };
77	}
