1	// MIA actions da Pronta Entrega v2 (câmara fria × expositora).
2	//
3	// Modelo novo: a página não tem mais kanban congelado/resfriado/expositor —
4	// os saldos vêm de `estoque` + `expositora_estoque` e as mutações passam
5	// pelos RPCs `mover_para_expositora` / `ajustar_expositora`.
6	//
7	// Handlers mantidos: pronta_search, pronta_refresh, clear_filters e
8	// pronta_create (semântica nova: abrir o modal "Expor na vitrine").
9	// Handlers de kanban (pronta_move, pronta_switch_view, pronta_consume,
10	// pronta_delete, pronta_open_detail, pronta_analytics_filter) foram
11	// removidos — backend MIA será atualizado na fase 2.
12	
13	import { useMemo } from 'react';
14	import { useMiaActions } from '@/hooks/useMiaActions';
15	import type { MiaActionHandler } from '@/types/mia';
16	
17	export interface ProntaEntregaMiaInterface {
18	  /** Preenche a busca por nome de produto. */
19	  setSearch: (value: string) => void;
20	  /** Refaz a query dos saldos (estoque + expositora). */
21	  refetch: () => void;
22	  /**
23	   * Abre o modal "Expor na vitrine" (mover_para_expositora). Com
24	   * `productName`, pré-seleciona o produto correspondente da lista.
25	   */
26	  openExporModal: (productName?: string) => void;
27	}
28	
29	/**
30	 * Registra os handlers MIA da rota /pronta-entrega.
31	 *
32	 * IMPORTANTE: `useMiaActions` registra os handlers UMA vez (não re-registra
33	 * em re-render) — os callbacks da interface devem ser estáveis (setState,
34	 * refetch do React Query, ou useCallback com refs).
35	 */
36	export function useMiaProntaEntregaActions(iface: ProntaEntregaMiaInterface): void {
37	  const { setSearch, refetch, openExporModal } = iface;
38	
39	  const handlers = useMemo<Record<string, MiaActionHandler>>(
40	    () => ({
41	      // ── Buscar produto ──
42	      pronta_search: {
43	        id: 'pronta_search',
44	        description: 'Buscar produto na pronta entrega (filtra a lista de saldos)',
45	        execute: (data) => {
46	          if (data?.search !== undefined) {
47	            setSearch(String(data.search));
48	          }
49	        },
50	      },
51	
52	      // ── Adicionar na vitrine (semântica nova do pronta_create) ──
53	      pronta_create: {
54	        id: 'pronta_create',
55	        description:
56	          'Abrir o modal de expor produto na vitrine (mover da câmara fria pra expositora)',
57	        execute: (data) => {
58	          openExporModal(
59	            data?.product_name !== undefined ? String(data.product_name) : undefined,
60	          );
61	        },
62	      },
63	
64	      // ── Atualizar dados ──
65	      pronta_refresh: {
66	        id: 'pronta_refresh',
67	        description: 'Atualizar os saldos da pronta entrega (câmara fria e expositora)',
68	        execute: () => {
69	          refetch();
70	        },
71	      },
72	
73	      // ── Limpar filtros ──
74	      clear_filters: {
75	        id: 'clear_filters',
76	        description: 'Limpar a busca da pronta entrega',
77	        execute: () => {
78	          setSearch('');
79	        },
80	      },
81	    }),
82	    [setSearch, refetch, openExporModal],
83	  );
84	
85	  useMiaActions('/pronta-entrega', handlers);
86	}
